package net.minecraft.world.item;import java.util.*;import net.minecraft.world.item.component.CustomData;public class ItemStack implements DefaultHolder{public final Object item;int count;final Map<Object,Object> data=new HashMap<>();public ItemStack(Object i,int n){item=i;count=n;}public Object getItem(){return item;}public int getCount(){return count;}public boolean isEmpty(){return count==0;}public void shrink(int n){count=Math.max(0,count-n);}public Map<Object,Object> storage(){return data;}public Object set(Object k,Object v){return data.put(k,v);}public ItemStack copy(){ItemStack s=new ItemStack(item,count);s.data.putAll(data);return s;}public ItemStack transmuteCopy(Object i,int n){ItemStack s=new ItemStack(i,n);s.data.putAll(data);return s;}}